#include <iostream>
#include <memory>

int main() {
    // Create a unique pointer to an integer
    auto uniquePtr = std::make_unique<int>(42);  // Exclusive ownership
    std::cout << "Value via unique_ptr: " << *uniquePtr << std::endl;

    // Create a shared pointer to a string
    auto sharedPtr = std::make_shared<std::string>("Hello, C++!");  // Shared ownership
    auto anotherSharedPtr = sharedPtr;  // Sharing the pointer
    std::cout << "Shared string: " << *sharedPtr << std::endl;

    // Demonstrate transfer of ownership with unique_ptr
    auto transferredPtr = std::move(uniquePtr);  // Move semantics
    if (transferredPtr) {
        std::cout << "Transferred value: " << *transferredPtr << std::endl;
    }
    // uniquePtr is now nullptr, avoiding dangling pointer issues

    return 0;
}
